  lit = lit * 1.08;
  let aces_a = lit * (2.51 * lit + vec3<f32>(0.03));
  let aces_b = lit * (2.43 * lit + vec3<f32>(0.59)) + vec3<f32>(0.14);
  lit = clamp(aces_a / aces_b, vec3<f32>(0.0), vec3<f32>(1.0));
